changeSet.sql:
-- 1. One workspace-owned connection per legacy config that was reachable: pointed at by a -- workspace, OR enabled (and therefore selectable by the mentor fallback and by -- detection's fan-out). This is where the irreplaceable thing lives: the encrypted key. INSERT INTO workspace_llm_connection (workspace_id, slug, display_name, base_url, api_protocol, auth_mode, api_key, enabled, created_at, updated_at) SELECT c.workspace_id, 'legacy-' || c.id, left(c.name, 128), COALESCE( NULLIF(btrim(c.llm_base_url), ''), CASE c.llm_provider WHEN 'OPENAI' THEN 'https://api.openai.com/v1' WHEN 'ANTHROPIC' THEN 'https://api.anthropic.com/v1' END, 'https://endpoint-not-migrated.invalid/v1'), 'openai-completions', 'BEARER', c.llm_api_key, false, COALESCE(c.created_at, now()), now() FROM agent_config c WHERE c.enabled OR EXISTS ( SELECT 1 FROM workspace w WHERE w.id = c.workspace_id AND (w.practice_config_id = c.id OR w.mentor_config_id = c.id));
-- 2. One model per carried-over connection, so every carried config can carry a binding. -- upstream_model_id is NOT NULL; a config that never named a model takes the -- 'model-not-migrated' placeholder rather than being skipped, because skipping it would -- also drop its binding and with it the execution limits, which survive nowhere else. -- The join to the connection is the filter — exactly the configs step 1 carried. -- model_version has no column here, so it is folded into the display name rather than -- dropped. INSERT INTO workspace_llm_model (workspace_id, connection_id, slug, display_name, upstream_model_id, supports_reasoning, pricing_mode, currency, enabled, created_at, updated_at) SELECT c.workspace_id, conn.id, 'legacy-' || c.id, left(c.name || COALESCE(' (' || NULLIF(btrim(c.model_version), '') || ')', ''), 128), COALESCE(NULLIF(btrim(c.model_name), ''), 'model-not-migrated'), false, 'UNPRICED', 'USD', false, COALESCE(c.created_at, now()), now() FROM agent_config c JOIN workspace_llm_connection conn ON conn.workspace_id = c.workspace_id AND conn.slug = 'legacy-' || c.id;
-- 3. One binding per (workspace, purpose), on the config the OLD RESOLVER would have picked -- — not on the pointer column, which was null far more often than it was set. Execution -- limits carry verbatim. Disabled, per the reasoning above. -- -- Practice detection: the pointed-at config when the pointer is set (enabled or not — a -- bound-but-disabled config paused detection, and a disabled binding is that same pause), -- otherwise the oldest enabled config, standing in for the fan-out that (workspace, -- purpose) uniqueness cannot represent. A pointer to a missing or foreign config joins to -- nothing and yields no binding, which is what it did before. INSERT INTO workspace_agent_binding (workspace_id, purpose, instance_model_id, workspace_model_id, timeout_seconds, max_concurrent_jobs, allow_internet, enabled, created_at, updated_at) SELECT b.workspace_id, 'PRACTICE_DETECTION', NULL, m.id, c.timeout_seconds, c.max_concurrent_jobs, c.allow_internet, false, now(), now() FROM ( SELECT w.id AS workspace_id, CASE WHEN w.practice_config_id IS NOT NULL THEN w.practice_config_id ELSE (SELECT min(x.id) FROM agent_config x WHERE x.workspace_id = w.id AND x.enabled) END AS config_id FROM workspace w ) b JOIN agent_config c ON c.id = b.config_id AND c.workspace_id = b.workspace_id JOIN workspace_llm_model m ON m.workspace_id = c.workspace_id AND m.slug = 'legacy-' || c.id;
-- Mentor: the pointed-at config only while it is enabled, otherwise the oldest enabled -- config — the mentor answered a user mid-conversation rather than going silent, so a -- disabled or dangling pointer fell through instead of pausing. INSERT INTO workspace_agent_binding (workspace_id, purpose, instance_model_id, workspace_model_id, timeout_seconds, max_concurrent_jobs, allow_internet, enabled, created_at, updated_at) SELECT b.workspace_id, 'MENTOR', NULL, m.id, c.timeout_seconds, c.max_concurrent_jobs, c.allow_internet, false, now(), now() FROM ( SELECT w.id AS workspace_id, COALESCE( (SELECT x.id FROM agent_config x WHERE x.id = w.mentor_config_id AND x.workspace_id = w.id AND x.enabled), (SELECT min(x.id) FROM agent_config x WHERE x.workspace_id = w.id AND x.enabled) ) AS config_id FROM workspace w ) b JOIN agent_config c ON c.id = b.config_id AND c.workspace_id = b.workspace_id JOIN workspace_llm_model m ON m.workspace_id = c.workspace_id AND m.slug = 'legacy-' || c.id;

