DO $$
BEGIN
    IF to_regclass('agent_config') IS NULL THEN
        RAISE EXCEPTION
            'Refusing to roll back changeSet 1785015307013-33: agent_config has already '
            'been dropped by changeSet -39, so the legacy-%% rows this would delete hold '
            'the only copy of every workspace''s encrypted LLM key. Roll forward instead, '
            'or restore agent_config from a backup first.';
    END IF;

    DELETE FROM workspace_agent_binding b
     USING workspace_llm_model m
     WHERE b.workspace_model_id = m.id AND m.slug LIKE 'legacy-%';
    DELETE FROM workspace_llm_model WHERE slug LIKE 'legacy-%';
    DELETE FROM workspace_llm_connection WHERE slug LIKE 'legacy-%';
END $$;

changeSet.sql:
DO $migration_report$
DECLARE
    needs_endpoint text;
    collapsed      text;
    dropped        text;
BEGIN
    IF to_regclass('agent_config') IS NULL THEN
        RETURN;
    END IF;

    -- (1) Carried over, but the endpoint, the protocol or the model id is a placeholder or
    --     a guess.
    SELECT string_agg(DISTINCT w.slug, ', ' ORDER BY w.slug) INTO needs_endpoint
    FROM agent_config c
    JOIN workspace w ON w.id = c.workspace_id
    WHERE (c.enabled
           OR w.practice_config_id = c.id
           OR w.mentor_config_id = c.id)
      AND (c.llm_provider <> 'OPENAI'
           OR NULLIF(btrim(c.llm_base_url), '') IS NULL
           OR NULLIF(btrim(c.model_name), '') IS NULL);

    IF needs_endpoint IS NOT NULL THEN
        RAISE WARNING 'Hephaestus #1368: AI configuration carried over with a placeholder endpoint, model id or non-OpenAI protocol in these workspaces: %. Their API keys, limits and any recorded model name were preserved; set a working endpoint and model in each workspace''s AI settings before re-enabling.', needs_endpoint;
    END IF;

    -- (2) Detection ran across several enabled configurations at once; one binding per
    --     (workspace, purpose) means only the oldest becomes the binding.
    SELECT string_agg(w.slug, ', ' ORDER BY w.slug) INTO collapsed
    FROM workspace w
    WHERE w.practice_config_id IS NULL
      AND (SELECT count(*) FROM agent_config c
            WHERE c.workspace_id = w.id AND c.enabled) > 1;

    IF collapsed IS NOT NULL THEN
        RAISE WARNING 'Hephaestus #1368: practice detection ran on SEVERAL configurations at once in these workspaces: %. The new model binds one model per purpose, so detection is bound to the oldest of them; the others were carried over as connections and models and can be bound to a purpose or deleted.', collapsed;
    END IF;

    -- (3) Dropped with the table: disabled AND unreferenced, so neither resolver could ever
    --     select it. Named anyway — it may hold a key the operator wants to revoke.
    SELECT string_agg(w.slug || '/' || c.name, ', ' ORDER BY w.slug || '/' || c.name) INTO dropped
    FROM agent_config c
    JOIN workspace w ON w.id = c.workspace_id
    WHERE NOT c.enabled
      AND w.practice_config_id IS DISTINCT FROM c.id
      AND w.mentor_config_id IS DISTINCT FROM c.id;

    IF dropped IS NOT NULL THEN
        RAISE WARNING 'Hephaestus #1368: these disabled, unreferenced AI configurations were NOT carried over and are dropped with the old table: %. Nothing could reach them, but each may hold an API key you want to revoke at the provider.', dropped;
    END IF;
END
$migration_report$;

CREATE INDEX CONCURRENTLY ix_agent_job_running_purpose
    ON agent_job (workspace_id, purpose)
    WHERE status = 'RUNNING';

